-- Generated by tools/generate_native_encounter_library.py from the public Bastion Library export.
return {
  ["acrylia-archmage-gorraferg-ring"] = {overview = {"Survive the grimling waves to draw out Archmage Gorraferg."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"Assemble before triggering the ring; the controller advances through eight wave stages.", "Pick up new grimlings promptly and keep the fighting area clear for the next wave.", "The last stage calls the archmage after a short delay. Save resources for that final opponent."}}}},
  ["acrylia-high-priest-gakkernog-ring"] = {overview = {"A sustained wave event ends with High Priest Gakkernog."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"Remain near the event trigger while clearing the waves.", "The wave sequence includes pauses and changes in the enemies summoned. Use those breaks to recover.", "Engage the high priest promptly when he appears; his unengaged appearance is temporary."}}}},
  ["acrylia-khati-sha-the-twisted"] = {overview = {"Break the warder and arcanist defenses before facing Khati Sha."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"Complete the warder and chanting sequence; Khati Sha is the final stage of the event.", "Clear the disruptive minions and distinguish the false arcanist from the true arcanists.", "Defeat the death guards before progressing the arcanist stage.", "Keep Khati Sha in his encounter area and be ready to control returning guards."}}}},
  ["acrylia-ring-of-fire"] = {overview = {"Fight through successive grimling rounds in the Ring of Fire."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"Prepare for repeated trash waves followed by stronger enemies.", "Keep tanks available for the named boss at the end of each round.", "Use gaps between spawns to recover and reposition before the next round."}}}},
  ["acrylia-trondol-shir-escort"] = {overview = {"Escort Trondol Shir through a guarded escape route."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"Have the group ready before the quest hand-in starts the escort.", "Clear the three guards and soulstealer promptly; the room-clear stage has a five-minute limit.", "Stay with Trondol until his final stop and complete the follow-up hand-in promptly."}}}},
  ["akheva-shei-vinitras"] = {overview = {"Shei Vinitras replaces his decoy with a raid encounter that punishes deaths."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"Expect the apparent Shei to give way to the real boss.", "Assign a plan for Death Touch and keep the raid stable; player and pet deaths can generate more enemies.", "Pick up the summoned adds quickly so one death does not become a chain of losses."}}}},
  ["akheva-the-insanity-crawler"] = {overview = {"The Insanity Crawler summons mind worms when it kills a player or pet."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"Keep players and pets alive to limit the number of mind worms.", "Have an add tank ready to collect four worms when a kill triggers them.", "The crawler has a limited appearance window, so assemble before engaging."}}}},
  ["anguish-arch-magus-vangl"] = {overview = {"Defeat Vangl while killing the converts and removing Mark of Death before its delayed check. The scripted focus announcements do not themselves change his combat statistics."}, roles = {{id = "tank", label = "Tanks", tips = {"Hold Vangl and collect each convert as it appears."}}, {id = "support", label = "Healers and support", tips = {"Arrange reliable mark removal before the thirty-second check."}}, {id = "damage", label = "Damage dealers", tips = {"Prioritize growing converts before returning to Vangl."}}}, phases = {{label = "Opening", trigger = "Above 75%", description = "Control recurring converts and remove marks before they resolve."}, {label = "Faster marks", trigger = "Below 75%", description = "The next mark scheduling uses a sixty-second cycle instead of seventy-five seconds."}, {label = "Final pressure", trigger = "10%", description = "Vangl casts Feedback Dispersion. Finish while continuing the existing add and mark mechanics."}}, abilities = {}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"Remove Mark of Death before its thirty-second check; a remaining mark triggers Cazic Touch.", "Kill languished converts quickly because their damage grows over time.", "Below 75%, subsequent mark cycles are shorter. At 10%, prepare for Feedback Dispersion."}}}},
  ["anguish-jelvan"] = {overview = {"Split into three teams and keep the tormentors within five health percentage points of one another. Losing balance removes Jelvan's blessing and progressively enables additional attacks."}, roles = {{id = "tank", label = "Tanks", tips = {"Hold one tormentor each inside the encounter area."}}, {id = "damage", label = "Damage dealers", tips = {"Shift damage to the highest-health tormentor to maintain balance."}}, {id = "healer", label = "Healers", tips = {"Expect more incoming spell pressure whenever the groups fall out of balance."}}}, phases = {}, abilities = {}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"Assign a tank and healing coverage to each tormentor.", "Keep the highest and lowest tormentors less than six health percentage points apart to retain the blessing.", "Health gaps of 11, 15 and 20 points enable additional spell timers. Correct the imbalance quickly.", "Keep the fight inside the arena and avoid a prolonged loss of combat."}}}},
  ["anguish-keldovan-the-harrier"] = {overview = {"Keep the pit-add kills flowing while a dedicated tank holds Keldovan. The recent-kill count weakens his defenses and abilities, but begins falling when kills stop."}, roles = {{id = "tank", label = "Tanks", tips = {"Keep a separate tank on the pit adds."}}, {id = "damage", label = "Damage dealers", tips = {"Continue killing adds instead of abandoning them once the boss is weakened."}}}, phases = {{label = "Build the advantage", trigger = "Initial engagement", description = "Kill the pit adds to accumulate the weakening effect."}, {label = "Maintain the advantage", trigger = "Throughout combat", description = "Continue add kills while damaging Keldovan; the recent-kill count decays after a gap."}}, abilities = {}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"Assign a group to the pit fiends and hounds while the main tank holds Keldovan.", "Recent add kills weaken the boss, but that advantage decays if kills stop.", "Keep healing and curse handling organized through his recurring combat spell rotation."}}}},
  ["anguish-overlord-mata-muram"] = {overview = {"Mata Muram requires fast personal reactions to his gaze, control of recurring adds, and a planned return after the raid is banished. Defeat Vangl before starting the initial dialogue."}, roles = {{id = "tank", label = "Tanks", tips = {"Keep the boss and recurring enemies controlled through each transition."}}, {id = "everyone", label = "Everyone", tips = {"React immediately to personal gaze and buzzing warnings."}}, {id = "support", label = "Healers and support", tips = {"Prepare mark removal for the short fifteen-second resolution window."}}}, phases = {{label = "Opening assault", trigger = "Initial engagement", description = "Control the coerced lieutenants and recurring lashers while responding to gaze warnings."}, {label = "Mark of Death", trigger = "70%", description = "The boss applies marks to randomly selected clients and checks for remaining marks fifteen seconds later."}, {label = "Converts", trigger = "50%", description = "Two languished converts appear. Collect and defeat them."}, {label = "Riftseeker intervention", trigger = "30%", description = "Four riftseekers appear and restrain Mata Muram. Banishment follows after sixty seconds, or sooner if his health falls below 20%."}, {label = "Return and finish", trigger = "After banishment", description = "The raid is moved away and Mata Muram retains his remaining health. Return correctly, reactivate him through dialogue and finish the encounter."}}, abilities = {{name = "Mata Muram's Gaze", summary = "A selected player has ten seconds to prepare Reflective Skin.", description = {"The script checks the selected player for Reflective Skin when the warning expires."}, tags = {"Personal responsibility"}, roles = {}}}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"When personally warned of the gaze, obtain Reflective Skin before ten seconds pass.", "A buzzing warning leads to five lashers at the selected player after six seconds; have add control ready.", "At 70%, remove Mark of Death before its fifteen-second check.", "After banishment, return through the encounter's intended route and use the boss dialogue to resume the fight."}}}},
  ["anguish-ture"] = {overview = {"Ture alternates ordinary combat with a short area-rampage window. Move the melee group out on the warning, keep the main tank covered, then return when the rampage ends."}, roles = {}, phases = {{label = "Combat", trigger = "Between rampages", description = "Maintain boss damage and heal through breath and destruction casts."}, {label = "Rampage warning", trigger = "Six-second warning", description = "Move vulnerable melee players out of the area."}, {label = "Area rampage", trigger = "Ten seconds", description = "Keep healing on the tank and wait for the rampage to end before moving back in."}}, abilities = {}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"Melee should move out when the rampage warning begins.", "The warning gives six seconds before a ten-second area-rampage window. Return after it ends.", "Keep the tank covered through recurring breath and destruction casts."}}}},
  ["anguish-warden-hanvar"] = {overview = {"Guard kills lower Hanvar's enforced health floor by five percentage points each. The raid needs twenty guard kills to remove the floor completely, while keeping the guards from sacrificing themselves."}, roles = {}, phases = {{label = "Protected warden", trigger = "Health floor begins at 100%", description = "Kill the five initial guards to begin lowering the floor."}, {label = "Returning guards", trigger = "Until twenty guard kills", description = "Kill replacement guards before their sacrifice timer completes; each death lowers the floor by another five points."}, {label = "Unprotected warden", trigger = "Twenty guard kills", description = "The floor reaches zero and the encounter stops requesting further replacements. Finish Hanvar."}}, abilities = {}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"Kill guards promptly: each actual guard death lowers the protected health floor by five points.", "A guard sacrifice casts Feedback Dispersion without advancing the kill count.", "Continue until twenty guard kills remove the health floor, then finish Hanvar.", "Keep the boss inside his encounter area and maintain healing through Chains and Wail of Anguish."}}}},
  ["barindu-ixvet-pox-colossus-of-war"] = {overview = {"Break the controllers' formation to face the Colossus of War and Ixvet Pox."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"Plan for the constructs to activate when their controllers enter combat.", "The poison quest sequence can disrupt the controllers; complete its setup before starting combat if using that route.", "Keep a tank ready for the colossus when controller deaths release it.", "Stay within the encounter area and finish Ixvet to complete the linked sequence."}}}},
  ["barindu-kyv-rux-vhedt"] = {overview = {"Kyv Rux Vhedt changes to a ranged attack pattern at low health."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"Expect the ranged behavior to begin at 45% health.", "Keep the group ready for volleys as the casting timer repeats.", "Maintain tank control while closing out the encounter."}}}},
  ["bothunder-agnarr-event-seasonal"] = {overview = {"The Agnarr Event is one tower assault with three bosses: Evynd Firestorm on the lower level, Emmerik Skyfury above him, and Agnarr the Storm Lord at the summit. Askr opens the route between stages.", "Each boss calls reinforcements from portals. Agnarr also summons four elemental bosses as his health falls, so the raid must handle timed waves and health-triggered reinforcements together."}, roles = {{id = "tank", label = "Tanks", tips = {"Assign tanks to portal reinforcements before each pull. The adds move toward the current boss.", "Prepare an extra tank as Agnarr approaches 99%, 76%, 51% and 26% health."}}, {id = "healer", label = "Healers", tips = {"Expect the first portal wave 30 seconds into combat, then another every two minutes while the boss remains engaged.", "Watch tanks handling new elemental bosses at Agnarr's health thresholds."}}, {id = "damage", label = "Damage dealers", tips = {"Help clear portal reinforcements before they overlap with the next wave.", "Coordinate damage near Agnarr's health thresholds so the raid is ready for each additional boss."}}}, phases = {{label = "Evynd Firestorm", trigger = "Lower tower", description = "Defeat Evynd while controlling the firestorm elementals called by his portals. After victory, ask the newly appeared Askr to transport you to the next level."}, {label = "Emmerik Skyfury", trigger = "Middle tower", description = "Defeat Emmerik while handling animated meteors from his celestial portals. Speak to Askr about the Storm, then hail the Chaos Vortex he creates to reach the summit."}, {label = "Agnarr and the first elemental boss", trigger = "Agnarr reaches 99% health", description = "The first elemental boss appears at Agnarr's position. Timed storm-portal reinforcements continue independently of his health."}, {label = "Second elemental boss", trigger = "Agnarr reaches 76% health", description = "Another elemental boss joins the fight at Agnarr's position."}, {label = "Third elemental boss", trigger = "Agnarr reaches 51% health", description = "A third elemental boss joins. Keep the new arrival controlled while portal waves continue."}, {label = "Final elemental boss", trigger = "Agnarr reaches 26% health", description = "The final elemental boss appears near Agnarr with a small random offset. Finish the reinforcements and defeat the Storm Lord."}, {label = "Speak with Karana", trigger = "Agnarr is defeated", description = "Karana and Askr appear. Hail Karana and follow the dialogue about the path of the Fallen to receive the character flags, then ask to be sent on your path when ready to leave."}}, abilities = {{name = "Firestorm portals", summary = "Evynd summons firestorm elementals through the portals.", description = {"The first call occurs 30 seconds after engagement, then repeats every two minutes. Each signaled firestorm portal creates an elemental and moves it toward Evynd."}, tags = {"Adds", "Timed waves"}, roles = {"tank", "damage"}}, {name = "Celestial portals", summary = "Emmerik summons animated meteors through the portals.", description = {"The first call occurs 30 seconds after engagement, then repeats every two minutes. Each signaled celestial portal creates an animated meteor and moves it toward Emmerik."}, tags = {"Adds", "Timed waves"}, roles = {"tank", "damage"}}, {name = "Storm portals", summary = "Agnarr calls random storm reinforcements toward the raid.", description = {"Thirty seconds after engagement, Agnarr strikes his staff and signals the storm portals. The call then repeats every two minutes.", "Each active outer portal selects one of four reinforcement types. The central portal does not create adds."}, tags = {"Adds", "Timed waves"}, roles = {"tank", "damage"}}, {name = "Elemental bosses", summary = "Four additional bosses arrive at 99%, 76%, 51% and 26% health.", description = {"These arrivals are triggered by Agnarr's health, independently of his timed portal waves. Prepare for overlapping reinforcements if several thresholds are crossed quickly."}, tags = {"Health thresholds", "Adds"}, roles = {"tank", "healer", "damage"}}}, sections = {{title = "Moving between stages", paragraphs = {"After Evynd, Askr remains for one hour and transports each player who asks. After Emmerik, Askr remains for 45 minutes; discussing the Storm opens a Chaos Vortex that also remains for 45 minutes. Hail the vortex to reach Agnarr."}, bullets = {"Evynd: hail Askr, then say transport.", "Emmerik: hail Askr, discuss the Storm, then hail the Chaos Vortex.", "Agnarr: speak with Karana before leaving; he remains for 20 minutes."}}, {title = "After a failed attempt", paragraphs = {"When Agnarr leaves combat, his portal timer stops, the four health thresholds reset, and his summoned storm reinforcements and elemental bosses are removed. A later reset timer repeats that cleanup after 20 minutes.", "Evynd and Emmerik stop their repeating portal timer when it checks and finds them out of combat. Their summoned elementals and meteors have a five-minute cleanup check that only removes them while they are not engaged."}, bullets = {}}, {title = "Seasonal completion", paragraphs = {"The seasonal zone controller skips the normal per-boss lockouts. Agnarr's defeat also creates a fragment of fractured time at his location.", "Hail the fragment and say bound to receive seasonal progression credit if you are an eligible seasonal character who has not received it. The fragment can bind up to 72 characters. It warns after ten minutes and disappears ten minutes later."}, bullets = {}}}},
  ["cantor-selindra"] = {overview = {"Cantor Selindra occupies the Castle Wings. Her shadow pulse shelters raiders near her, requiring ranged players and healers to close the distance on command."}, roles = {{id = "tank", label = "Tanks", tips = {"Keep Selindra accessible so the raid can gather around her.", "Avoid repositioning her away from the gathering raid during the warning."}}, {id = "healer", label = "Healers", tips = {"Move within 20 paces of Selindra before the warning ends.", "Choose a position that allows healing while remaining inside the sheltered area."}}, {id = "damage", label = "Damage dealers", tips = {"Ranged players should close in immediately when the shadows deepen.", "Bring pets inside the sheltered area as well."}}}, phases = {{label = "Break the Choir Seal", trigger = "Throughout combat", description = "A gathering warning repeats every 22 seconds. After six seconds, the pulse strikes targets more than 20 and up to 180 paces from Selindra."}}, abilities = {{name = "Sheltering Shadows", summary = "Gather within 20 paces of Selindra before the six-second warning ends.", description = {"Selindra is the center of the sheltered area when the pulse resolves. Stay close enough to follow if she moves.", "Raiders and pets outside the sheltered area but within the outer pulse radius can be struck if they have line of sight to its center."}, tags = {"Gather", "Six-second warning"}, roles = {"tank", "healer", "damage"}}}, sections = {{title = "Stay in the battle", paragraphs = {"Fight near the boss's home. Raiders and their pets must remain within 180 paces of the boss and within 30 paces vertically; attacks and aid from outside that boundary are rejected.", "If no eligible living raider remains in the arena, or the boss is pulled too far from home, a warning precedes an encounter reset. Keep healers and resurrection targets inside the battle."}, bullets = {}}, {title = "Read the warnings", paragraphs = {"Mechanic warnings appear in the Event Messages chat filter. Movement mechanics give six seconds to respond.", "Ground markers can supplement the warning when supported and enabled. Follow the chat instruction even if a marker is absent."}, bullets = {}}, {title = "Seasonal victory", paragraphs = {"A confirmed seasonal kill announces the guild or character victory, identifying the regular or Bloodbound covenant. Pet kills credit their player owner. In-game announcements use the Event Messages chat filter."}, bullets = {}}}},
  ["bloodbound-cantor-selindra"] = {overview = {"Bloodbound Cantor Selindra conducts the Castle Wings with a reversed refrain. Her first pulse rewards gathering close; the answering pulse punishes anyone who stays there."}, roles = {{id = "tank", label = "Tanks", tips = {"Keep Selindra accessible and avoid moving her away from the gathering raid.", "After the first pulse, retreat more than 35 paces with the raid while keeping the fight near her home."}}, {id = "healer", label = "Healers", tips = {"Move within 20 paces for the first six-second warning.", "Heal during the transition, then get more than 35 paces away before the second warning ends."}}, {id = "damage", label = "Damage dealers", tips = {"Ranged players must move in for the first warning and back out for the second.", "Move pets with the raid. A pet safely inside the first shelter is still exposed to the following ring."}}}, phases = {{label = "Sheltering Shadows", trigger = "An 18-second repeating ability cycle", description = "Gather within 20 paces of Selindra during the six-second warning. The first pulse strikes the surrounding area beyond that shelter."}, {label = "Break the answering ring", trigger = "Immediately after the gathering pulse", description = "The rite reverses into a second six-second warning. Move more than 35 paces from Selindra before the next pulse."}}, abilities = {{name = "Sheltering Shadows", summary = "Gather within 20 paces for the first pulse.", description = {"Selindra's current position is the center of the sheltered area. The gathering warning lasts six seconds.", "At resolution, raiders and pets more than 20 and up to 180 paces away can be struck when they have line of sight to the pulse center. Hold the safe position until this first pulse has resolved."}, tags = {"Gather", "Six-second warning"}, roles = {"tank", "healer", "damage"}}, {name = "Answering Ring", summary = "Leave the shelter and move more than 35 paces away for the second pulse.", description = {"The first pulse immediately begins a new six-second retreat warning. Selindra remains the center, but the safe position has changed.", "The second pulse strikes raiders and pets within 35 paces and in line of sight. Staying in the previous green shelter will not protect you from it."}, tags = {"Retreat", "Reversal", "Six-second warning"}, roles = {"tank", "healer", "damage"}}}, sections = {{title = "Awaken the guardian", paragraphs = {"Defeat the native servants in the Castle Wings. The guardian answers after a saved random threshold of 15 to 20 kills in that district.", "Summoned shades and other encounter adds do not advance this district requirement."}, bullets = {}}, {title = "Stay in the battle", paragraphs = {"Fight near the boss's home. Raiders and their pets must remain within 180 paces of the boss and within 30 paces vertically; attacks and aid from outside that boundary are rejected.", "If no eligible living raider remains in the arena, or the boss is pulled too far from home, a warning precedes an encounter reset. Keep healers and resurrection targets inside the battle."}, bullets = {}}, {title = "Follow both warnings", paragraphs = {"Both instructions appear in the Event Messages chat filter. Respond to the current warning rather than repeating the normal covenant's gathering pattern.", "The first marker is a green 20-pace shelter. The next marker marks the 35-pace danger area. Ground markers supplement the warnings; neither mechanic depends on their presence."}, bullets = {}}, {title = "Choose the seal bearers", paragraphs = {"Assign the two seal looters before the guardian falls. Each character may claim only one guardian seal for this expedition, even if that seal is later destroyed or left on a corpse.", "The seals are reusable, temporary items bound to this instance. Keep them with their chosen bearers as the raid continues."}, bullets = {}}, {title = "Seasonal victory", paragraphs = {"A confirmed seasonal kill announces the guild or character victory, identifying the regular or Bloodbound covenant. Pet kills credit their player owner. In-game announcements use the Event Messages chat filter."}, bullets = {}}}},
  ["castellan-veyr"] = {overview = {"Castellan Veyr commands the Courtyard and Battlements. His crimson brand picks a raider and follows that player, making controlled separation the central mechanic."}, roles = {{id = "tank", label = "Tanks", tips = {"Keep Veyr near his home with space for the branded raider to move away.", "If you receive the brand, separate from the raid without dragging the fight beyond its boundary."}}, {id = "healer", label = "Healers", tips = {"Keep the branded raider in healing range while staying more than 25 paces away.", "Prepare to heal the marked player after the blast; moving away protects nearby allies, not the brand's bearer."}}, {id = "damage", label = "Damage dealers", tips = {"If marked, move away from the raid immediately. The blast follows your position.", "Keep more than 25 paces from the marked player and move pets out of the blast."}}}, phases = {{label = "Break the Keep Seal", trigger = "Throughout combat", description = "A crimson brand warning repeats every 22 seconds. A random eligible raider is marked; the blast resolves six seconds later around that player's position."}}, abilities = {{name = "Crimson Brand", summary = "Give the marked raider more than 25 paces of space.", description = {"The chosen player receives a private warning in addition to the raid announcement. After six seconds, the brand erupts around that player's current location.", "The blast can hit the marked raider, nearby raiders and pets. Crossing the combat boundary does not leave the brand behind."}, tags = {"Spread", "Marked player", "Six-second warning"}, roles = {"tank", "healer", "damage"}}}, sections = {{title = "Stay in the battle", paragraphs = {"Fight near the boss's home. Raiders and their pets must remain within 180 paces of the boss and within 30 paces vertically; attacks and aid from outside that boundary are rejected.", "If no eligible living raider remains in the arena, or the boss is pulled too far from home, a warning precedes an encounter reset. Keep healers and resurrection targets inside the battle."}, bullets = {}}, {title = "Read the warnings", paragraphs = {"Mechanic warnings appear in the Event Messages chat filter. Movement mechanics give six seconds to respond.", "Ground markers can supplement the warning when supported and enabled. Follow the chat instruction even if a marker is absent."}, bullets = {}}, {title = "Seasonal victory", paragraphs = {"A confirmed seasonal kill announces the guild or character victory, identifying the regular or Bloodbound covenant. Pet kills credit their player owner. In-game announcements use the Event Messages chat filter."}, bullets = {}}}},
  ["bloodbound-castellan-veyr"] = {overview = {"Bloodbound Castellan Veyr commands the Courtyard and Battlements with a paired attack. A moving brand tests the raid's spacing before a second blast forces everyone away from the Castellan."}, roles = {{id = "tank", label = "Tanks", tips = {"Hold Veyr near his home and leave an escape lane for a marked raider.", "After the brand erupts, move more than 35 paces from Veyr for the second warning."}}, {id = "healer", label = "Healers", tips = {"Stay more than 25 paces from the branded raider while keeping that player in healing range.", "Be ready to heal the brand bearer, then move out of the boss-centered ring yourself."}}, {id = "damage", label = "Damage dealers", tips = {"If marked, move away from other raiders and pets immediately.", "After the brand resolves, watch Veyr rather than the former brand location and retreat more than 35 paces from him."}}}, phases = {{label = "Separate the brand", trigger = "An 18-second repeating ability cycle", description = "A random eligible raider receives a crimson brand. Six seconds later, the blast follows that player's current position and strikes within 25 paces."}, {label = "Break the ring", trigger = "Immediately after the brand resolves", description = "A second six-second warning marks the area around Veyr. Move more than 35 paces from the boss before this pulse."}}, abilities = {{name = "Crimson Brand", summary = "Give the branded player more than 25 paces of space.", description = {"The selected raider receives a private Event Messages warning as well as the raid announcement. The brand follows that exact player until its six-second warning ends.", "The bearer can be struck along with nearby raiders and pets. Crossing the battle boundary does not leave the brand behind; move away from allies rather than expecting to escape it."}, tags = {"Spread", "Marked player", "Six-second warning"}, roles = {"tank", "healer", "damage"}}, {name = "Reversing Ring", summary = "After the brand, move more than 35 paces from Veyr.", description = {"The brand's resolution immediately begins another six-second warning. This time, Veyr is the center of the danger.", "The pulse follows the boss's current position and can strike raiders and pets within 35 paces and in line of sight. Remaining clear of the branded player alone is no longer sufficient."}, tags = {"Retreat", "Reversal", "Six-second warning"}, roles = {"tank", "healer", "damage"}}}, sections = {{title = "Awaken the guardian", paragraphs = {"Defeat the native servants in the Courtyard and Battlements. The guardian answers after a saved random threshold of 15 to 20 kills in that district.", "Summoned shades and other encounter adds do not advance this district requirement."}, bullets = {}}, {title = "Stay in the battle", paragraphs = {"Fight near the boss's home. Raiders and their pets must remain within 180 paces of the boss and within 30 paces vertically; attacks and aid from outside that boundary are rejected.", "If no eligible living raider remains in the arena, or the boss is pulled too far from home, a warning precedes an encounter reset. Keep healers and resurrection targets inside the battle."}, bullets = {}}, {title = "Follow both warnings", paragraphs = {"The Event Messages filter carries both warnings. Each step gives six seconds; the second begins as soon as the first blast resolves.", "The brand marker follows the selected player with a 25-pace radius. The next marker follows Veyr with a 35-pace radius. Use the changing center to choose your escape route."}, bullets = {}}, {title = "Choose the seal bearers", paragraphs = {"Assign the two seal looters before the guardian falls. Each character may claim only one guardian seal for this expedition, even if that seal is later destroyed or left on a corpse.", "The seals are reusable, temporary items bound to this instance. Keep them with their chosen bearers as the raid continues."}, bullets = {}}, {title = "Seasonal victory", paragraphs = {"A confirmed seasonal kill announces the guild or character victory, identifying the regular or Bloodbound covenant. Pet kills credit their player owner. In-game announcements use the Event Messages chat filter."}, bullets = {}}}},
  ["gravekeeper-vhal"] = {overview = {"Gravekeeper Vhal holds the Graveyard and Mausoleum. His repeating ring of blood tests the raid's ability to move out together and return without leaving the battle."}, roles = {{id = "tank", label = "Tanks", tips = {"Keep Vhal near his home and preserve room for the raid to retreat.", "Move more than 35 paces from Vhal before the ring erupts, then reestablish position."}}, {id = "healer", label = "Healers", tips = {"Plan movement with the raid during the six-second warning.", "Stay within the battle boundary while healing raiders who are retreating."}}, {id = "damage", label = "Damage dealers", tips = {"Leave melee range immediately when the ring warning appears.", "Move pets out of the ring as well; the pulse can strike them."}}}, phases = {{label = "Break the Grave Seal", trigger = "Throughout combat", description = "A ring warning repeats every 22 seconds. After a six-second warning, a pulse strikes targets within 35 paces of Vhal's position."}}, abilities = {{name = "Ring of Blood", summary = "Move more than 35 paces away before the six-second warning ends.", description = {"The pulse is centered on Vhal when it resolves, so moving the boss also moves the danger.", "Raiders and pets within the ring and in line of sight of its center can be struck. Return after the pulse while keeping the fight near Vhal's home."}, tags = {"Movement", "Six-second warning"}, roles = {"tank", "healer", "damage"}}}, sections = {{title = "Stay in the battle", paragraphs = {"Fight near the boss's home. Raiders and their pets must remain within 180 paces of the boss and within 30 paces vertically; attacks and aid from outside that boundary are rejected.", "If no eligible living raider remains in the arena, or the boss is pulled too far from home, a warning precedes an encounter reset. Keep healers and resurrection targets inside the battle."}, bullets = {}}, {title = "Read the warnings", paragraphs = {"Mechanic warnings appear in the Event Messages chat filter. Movement mechanics give six seconds to respond.", "Ground markers can supplement the warning when supported and enabled. Follow the chat instruction even if a marker is absent."}, bullets = {}}, {title = "Seasonal victory", paragraphs = {"A confirmed seasonal kill announces the guild or character victory, identifying the regular or Bloodbound covenant. Pet kills credit their player owner. In-game announcements use the Event Messages chat filter."}, bullets = {}}}},
  ["bloodbound-gravekeeper-vhal"] = {overview = {"In the Bloodbound covenant, Gravekeeper Vhal turns the Graveyard and Mausoleum into a test of two opposite movements. Escaping his ring is only the first half of the rite."}, roles = {{id = "tank", label = "Tanks", tips = {"Keep Vhal near his home with a clear route for the raid to move out and back in.", "Retreat more than 35 paces for the first pulse, then gather within 20 paces of Vhal for the second."}}, {id = "healer", label = "Healers", tips = {"Time healing around two consecutive six-second movement windows.", "Follow the raid back into the green sheltered area as soon as the retreat pulse has resolved."}}, {id = "damage", label = "Damage dealers", tips = {"Leave melee range promptly for the ring, then close back in for the gathering warning.", "Reposition pets for both pulses; remaining safely outside after the first blast is dangerous during the second."}}}, phases = {{label = "Ring of Blood", trigger = "An 18-second repeating ability cycle", description = "A six-second warning precedes a pulse within 35 paces of Vhal. Move more than 35 paces away."}, {label = "Shelter in the grave shadow", trigger = "Immediately after the retreat pulse", description = "A second six-second warning reverses the required movement. Gather within 20 paces of Vhal before the surrounding shadows strike."}}, abilities = {{name = "Ring of Blood", summary = "Move more than 35 paces away during the first six-second warning.", description = {"The first pulse is centered on Vhal when it resolves. Raiders and pets within 35 paces and in line of sight of that point can be struck.", "Wait for this pulse to resolve before returning. The next warning immediately changes the safe position."}, tags = {"Retreat", "Six-second warning"}, roles = {"tank", "healer", "damage"}}, {name = "Reversing Shadows", summary = "Return within 20 paces during the second six-second warning.", description = {"As soon as the ring erupts, Vhal begins a gathering warning. The sheltered area follows his current position.", "At the end of that warning, the pulse strikes raiders and pets more than 20 and up to 180 paces from Vhal when they have line of sight to its center. Do not remain at the first pulse's safe distance."}, tags = {"Gather", "Reversal", "Six-second warning"}, roles = {"tank", "healer", "damage"}}}, sections = {{title = "Awaken the guardian", paragraphs = {"Defeat the native servants in the Graveyard and Mausoleum. The guardian answers after a saved random threshold of 15 to 20 kills in that district.", "Summoned shades and other encounter adds do not advance this district requirement."}, bullets = {}}, {title = "Stay in the battle", paragraphs = {"Fight near the boss's home. Raiders and their pets must remain within 180 paces of the boss and within 30 paces vertically; attacks and aid from outside that boundary are rejected.", "If no eligible living raider remains in the arena, or the boss is pulled too far from home, a warning precedes an encounter reset. Keep healers and resurrection targets inside the battle."}, bullets = {}}, {title = "Follow both warnings", paragraphs = {"Warnings appear in the Event Messages chat filter. Each movement has its own six-second response window.", "The retreat marker shows the 35-pace danger area. The following green marker shows the 20-pace shelter. Follow the chat instruction even if ground markers are absent."}, bullets = {}}, {title = "Choose the seal bearers", paragraphs = {"Assign the two seal looters before the guardian falls. Each character may claim only one guardian seal for this expedition, even if that seal is later destroyed or left on a corpse.", "The seals are reusable, temporary items bound to this instance. Keep them with their chosen bearers as the raid continues."}, bullets = {}}, {title = "Seasonal victory", paragraphs = {"A confirmed seasonal kill announces the guild or character victory, identifying the regular or Bloodbound covenant. Pet kills credit their player owner. In-game announcements use the Event Messages chat filter."}, bullets = {}}}},
  ["huntmaster-draeven"] = {overview = {"Huntmaster Draeven stalks the Ravine and Crypt. He repeatedly raises shades, turning the encounter into a fight for control of accumulating adds."}, roles = {{id = "tank", label = "Tanks", tips = {"Pick up new shades promptly and keep the battle near Draeven's home.", "Watch for renewed shades returning at full strength if older adds survive too long."}}, {id = "healer", label = "Healers", tips = {"Expect pressure to rise when shades spawn and when surviving shades renew.", "Stay on the battle's floor and inside the boundary so healing is accepted."}}, {id = "damage", label = "Damage dealers", tips = {"Assign damage to shades before their one-minute renewal.", "Use the fifteen-second warning to finish older shades before they return at full strength."}}}, phases = {{label = "Break the Hunt Seal", trigger = "Every 30 seconds during combat", description = "Draeven attempts to summon two shades, up to four living shades at a time. Shades that survive for one minute are replaced by renewed shades."}}, abilities = {{name = "Risen Shades", summary = "Defeat the adds before their one-minute renewal.", description = {"Draeven summons two shades every 30 seconds while fewer than four are alive. They enter the battle against eligible raiders.", "At 45 seconds of age, a warning announces that the oldest shades have fifteen seconds remaining. At one minute, surviving shades dissolve and are replaced at full strength."}, tags = {"Adds", "Priority target"}, roles = {"tank", "healer", "damage"}}}, sections = {{title = "Stay in the battle", paragraphs = {"Fight near the boss's home. Raiders and their pets must remain within 180 paces of the boss and within 30 paces vertically; attacks and aid from outside that boundary are rejected.", "If no eligible living raider remains in the arena, or the boss is pulled too far from home, a warning precedes an encounter reset. Keep healers and resurrection targets inside the battle."}, bullets = {}}, {title = "Control the hunt", paragraphs = {"Use the oldest-shade warning to set priorities. Leaving an almost defeated shade alive through its renewal loses the damage already dealt."}, bullets = {}}, {title = "Seasonal victory", paragraphs = {"A confirmed seasonal kill announces the guild or character victory, identifying the regular or Bloodbound covenant. Pet kills credit their player owner. In-game announcements use the Event Messages chat filter."}, bullets = {}}}},
  ["bloodbound-huntmaster-draeven"] = {overview = {"Bloodbound Huntmaster Draeven rules the Ravine and Crypt through a living blood pack. His shades protect him while a delayed brand forces the raid to keep moving through the add fight."}, roles = {{id = "tank", label = "Tanks", tips = {"Collect each new shade wave promptly while keeping Draeven near his home.", "Leave space for a branded raider to separate from the raid without dragging adds through the healers."}}, {id = "healer", label = "Healers", tips = {"Expect pressure when up to three new shades join the fight.", "Keep the branded raider in healing range while staying more than 25 paces away from that player."}}, {id = "damage", label = "Damage dealers", tips = {"Prioritize the shades: Draeven takes only 20 percent damage while any shade bound to him survives.", "Finish older shades before their one-minute renewal. Reposition pets and spread promptly when a brand appears."}}}, phases = {{label = "Break the blood pack", trigger = "Every 26 seconds during combat", description = "Draeven attempts to summon up to three shades, capped at four living shades. While any of his shades survives, incoming damage to Draeven is reduced to 20 percent."}, {label = "Separate the prey", trigger = "Six seconds after the shade summons", description = "A random eligible raider receives a brand with its own six-second warning. The ensuing blast follows that player and strikes within 25 paces."}, {label = "Finish the old shades", trigger = "A shade survives for one minute", description = "An age warning gives roughly fifteen seconds to finish the oldest shades. Surviving shades dissolve at one minute and are replaced at full strength."}}, abilities = {{name = "Blood Pack", summary = "Destroy every bound shade to restore full damage against Draeven.", description = {"Every 26 seconds Draeven attempts to add up to three shades, with at most four living shades at once. New shades attack eligible raiders.", "Any surviving shade bound to Draeven grants him 80 percent damage reduction. Damage returns to normal once none remain.", "The oldest-shade warning begins around 45 seconds of age. Shades surviving to one minute reform at full strength, so allowing a nearly defeated add to renew wastes the damage already dealt."}, tags = {"Adds", "Damage reduction", "Priority target"}, roles = {"tank", "healer", "damage"}}, {name = "Hunting Brand", summary = "Keep more than 25 paces from the marked player.", description = {"Six seconds after the summon, the hunting brand appears on a random eligible raider. That raider then has a full six-second warning before the blast.", "The blast follows the bearer's current position, can strike that player as well as nearby raiders and pets, and is not left behind by crossing the combat boundary. Keep handling the shades while making room for the brand."}, tags = {"Spread", "Marked player", "Six-second warning"}, roles = {"tank", "healer", "damage"}}}, sections = {{title = "Awaken the guardian", paragraphs = {"Defeat the native servants in the Ravine and Crypt. The guardian answers after a saved random threshold of 15 to 20 kills in that district.", "Summoned shades and other encounter adds do not advance this district requirement."}, bullets = {}}, {title = "Stay in the battle", paragraphs = {"Fight near the boss's home. Raiders and their pets must remain within 180 paces of the boss and within 30 paces vertically; attacks and aid from outside that boundary are rejected.", "If no eligible living raider remains in the arena, or the boss is pulled too far from home, a warning precedes an encounter reset. Keep healers and resurrection targets inside the battle."}, bullets = {}}, {title = "Follow both warnings", paragraphs = {"Read the Event Messages filter for the pack summons, hunting brand and oldest-shade warning. The hunting brand has its own six-second warning after the initial six-second delay.", "When available, a 25-pace ground marker follows the branded player. The warning and blast still apply if markers are absent."}, bullets = {}}, {title = "Choose the seal bearers", paragraphs = {"Assign the two seal looters before the guardian falls. Each character may claim only one guardian seal for this expedition, even if that seal is later destroyed or left on a corpse.", "The seals are reusable, temporary items bound to this instance. Keep them with their chosen bearers as the raid continues."}, bullets = {}}, {title = "Seasonal victory", paragraphs = {"A confirmed seasonal kill announces the guild or character victory, identifying the regular or Bloodbound covenant. Pet kills credit their player owner. In-game announcements use the Event Messages chat filter."}, bullets = {}}}},
  ["mistmoore-the-archivist-s-midnight-vigil"] = {overview = {"Explore Mistmoore with a small group, defeat its servants and recover forbidden relics during the Archivist’s Midnight Vigil."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"The Archivist admits a group of three to six characters of level 50 or higher. The expedition lasts eight hours.", "Defeat eligible servants and named enemies throughout the castle. Each new relic requires a randomly chosen eighteen to thirty-three qualifying kills.", "A relic appears on the corpse that completes the current kill requirement. Watch the lantern announcement and check that corpse before moving on.", "Each set contains all four relic types in a shuffled order, then begins a new set. Ordinary respawns allow continued hunting during the expedition.", "Named enemies provide one selection from their own two-item equipment pool. Only current expedition members may claim the spoils.", "The Vigil uses its own group expedition, progression and admission rules. Keep the group together and maintain current membership when returning to the zone."}}}},
  ["westkorlachb-find-fibblebrap-2-lost-caverns"] = {overview = {"Explore the Lost Caverns until Captain Therimel's confrontation opens the final fight."}, roles = {{id = "everyone", label = "Everyone", tips = {"Finish the exploration stage, let the dialogue complete, and prepare before the captain's protection drops."}}}, phases = {}, abilities = {}, sections = {{title = "Encounter plan", paragraphs = {}, bullets = {"The mission supports task brackets from level 50 through 68 and above, scaling the zone's enemies for the active task.", "Completing task stage three moves the captain to his destination and starts the exchange with Therigal's Scholar.", "After the scholar's scripted death, the captain becomes attackable.", "Task completion creates a reward chest, and the exit door returns players to Stoneroot Falls."}}}},
  ["chardokb-korucust"] = {overview = {"Korucust pairs recurring spell attacks with a transformation at 40% health."}, roles = {}, phases = {}, abilities = {{name = "Cloud and Vengeance", summary = "Two linked casts pressure the current tank.", description = {}, tags = {"Tank pressure"}, roles = {}}, {name = "Phantasmal Shift", summary = "Korucust transforms at 40% health.", description = {}, tags = {"Health phase"}, roles = {}}}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"Prepare for Cloud of Oblivion ten seconds after the pull, then once each minute.", "Korucust's Vengeance follows the cloud by two seconds.", "At 40%, Korucust casts Phantasmal Shift. Keep tank control through the transition."}}}},
  ["chardokb-leprous-chokidai"] = {overview = {"Weaken the leprous chokidai to complete its ranger quest interaction."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"Lower the chokidai to 25% to begin the capture checks.", "The ranger must have dealt damage and hold the required capture tool in the primary slot; keep the chokidai alive while waiting for capture.", "A death triggers Epidermal Rot against a random hated target."}}}},
  ["citymist-black-reaver-lord-ghiosk-lord-rak-ashiir-chain"] = {overview = {"Black reavers can continue into replacement enemies and named opponents."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"Keep a tank ready at the death location because a replacement may appear immediately.", "The normal reaver chain can produce a shadow, Ghiosk or another reaver. Clearing the last normal reaver can call Rak'Ashiir.", "A separate reaver script chooses normal or fabled named opponents from the active content flag."}}}},
  ["cobaltscar-gnashing-killer-shark-and-companions"] = {overview = {"A shaman quest summons a dangerous shark and two companions beneath Cobalt Scar."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"Have underwater travel and combat preparations ready before speaking with Yoppa.", "The eligible shaman starts the encounter through the quest dialogue.", "Collect all three sharks and focus the group on one target at a time."}}}},
  ["corathus-taskmaster"] = {overview = {"Clear the reapers, then stop their repair support when Taskmaster XVII activates."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"Defeat all four active creep reapers to summon the Taskmaster.", "At 75%, the Taskmaster begins its repair sequence and activates further reapers.", "Destroy active repair adds promptly to reduce the boss's regeneration."}}}},
  ["corathusb-find-fibblebrap1-the-mines"] = {overview = {"Search the mines for Fibblebrap's gem and deal with Creeper Clicktok."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"Follow the mine objectives and recover the required memory fragment.", "For the combat route, hail Creeper Clicktok without carrying the requested larva meat. He becomes attackable after two five-second dialogue delays.", "Defeat Clicktok and loot the gem to advance its mission objective.", "Complete the pickup and loot objectives before returning through the mission route."}}}},
  ["nadox-the-luggald-broodmother"] = {overview = {"Follow the Luggald Broodmother’s procession and defeat the defenders it leaves along the route."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"The procession creates increasingly large groups of defenders and archseekers at successive waypoints.", "Clear the waves while following its route; the final stop replaces the moving NPC with the hostile Broodmother.", "The final encounter has a one-hour depop timer that pauses during combat. Its cleanup also removes remaining procession defenders."}}}},
  ["cauldron-praklion-of-the-cauldron"] = {overview = {"Praklion retreats twice before the quest fight can be completed."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"At 70% and 30%, Praklion wipes threat and moves to a new location.", "Follow the retreat and wait for the brief immunity to end before rebuilding threat.", "Allow both retreats to happen; the second stage enables the quest-specific drop."}}}},
  ["dawnshroud-hunter-s-pike-beast-challenge"] = {overview = {"Defeat the summoned beasts and their successors for the Hunter's Pike quest."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"The quest hand-in to Carre Harger brings out two initial beasts.", "Each initial beast produces a successor on death; keep the group ready for the next target.", "Complete both branches before returning with the required quest proof."}}}},
  ["guke-deepest-guk-raid-executioner-gimdk-first-witness"] = {overview = {"Tell Scout Mainil you are ready. Split the raid to escort him while protecting Scout Granos at the entrance, then follow their routes deeper into the prison.", "One force must stop the Executioner's Risen from becoming souls for the cauldron while the other destroys the Energy, Matter and Spirit foci. Destroying all three foci removes the protection from both the Executioner and the First Witness."}, roles = {}, phases = {{label = "Protect the scouts", trigger = "Tell Mainil ready", description = "Keep both scouts alive as they separate. Mainil's route directs one force to the Executioner; Granos leads the other toward the foci."}, {label = "Souls and foci", trigger = "Both routes reach their objectives", description = "Kill Risen before their 30-second transformation and stop souls reaching the cauldron, which otherwise creates reinforcements near the First Witness. Destroy all three foci."}, {label = "Finish both bosses", trigger = "All foci destroyed", description = "Kill Gimdk before the First Witness if pursuing the additional Executioner chest. Both scouts must still be alive when the reward checks occur."}}, abilities = {{name = "Focus spells", summary = "Each focus casts its own spells during combat.", description = {"Energy uses Blurring Focus and Life Vortex; Matter uses Everlasting Essence and Swirling Matter; Spirit uses Infinite Mass. Their actual effects depend on the loaded spell data."}, tags = {}, roles = {}}}, sections = {{title = "Completion checks", paragraphs = {"With both scouts alive, the First Witness death creates the foci and witness chests. The extra Gimdk chest additionally requires the Executioner death flag to have been earned first. Completion adds a four-and-a-half-day replay lockout to the expedition."}, bullets = {}}}},
  ["gukg-gragna-the-cursed"] = {overview = {"Gragna appears after the Cursed Spore stage. Follow the Knight of Gukta's call toward the next chamber and keep Gragna inside that encounter area.", "Every 65 seconds while engaged, the script announces the four healers and casts Mithaniel's Blessing at Gragna's current hate leader."}, roles = {}, phases = {}, abilities = {{name = "Mithaniel's Blessing", summary = "A repeating 65-second spell targets the current hate leader.", description = {}, tags = {}, roles = {}}, {name = "Encounter boundary", summary = "Pulling Gragna west of X -380 resets the fight.", description = {"A six-second check casts Balance of the Nameless on Gragna, removes buffs, returns Gragna home and clears the hate list."}, tags = {}, roles = {}}}, sections = {}},
  ["gukg-the-cavern-creeper"] = {overview = {"Defeat the Cavern Creeper after Leklos falls to continue the raid."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"Follow the chanting deeper into the cavern after defeating Leklos.", "Tank the Cavern Creeper while the evokers perform their ritual.", "Continue steady damage through the ritual announcements at 85%, 75% and 60%."}}}},
  ["pofire-fennin-ro-tyrant-of-fire"] = {overview = {"Defeat Doomfire’s armies and Council of Fire to reach Fennin Ro."}, roles = {}, phases = {{label = "Doomfire army", trigger = "Guardian of Doomfire defeated", description = "Clear all required first-stage formations."}, {label = "Bridge", trigger = "First army cleared", description = "Defeat the bridge forces and their four leaders."}, {label = "Council of Fire", trigger = "Bridge cleared", description = "Defeat all four council opponents."}, {label = "Fennin Ro", trigger = "Council defeated", description = "Control the elite guardians and defeat the Tyrant of Fire."}}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"Defeating the Guardian of Doomfire begins the timed sequence.", "Clear the first army formations, then the bridge forces and four named leaders: Reaxnous, Azobian, Hebabbilys and Javonn.", "Defeat Chancellor Kirtra, Chancellor Traxom, Omni Magus Crato and Warlord Prollaz to summon Fennin Ro.", "The final phase also enables elite guardians. Keep the route controlled while establishing the main tank on Fennin.", "A fresh event begins with a two-hour limit. Existing expedition phase lockouts can resume the encounter at a later stage with a shorter remaining allowance."}}}},
  ["necropolis-garzicor-s-corpse-and-wraith"] = {overview = {"Release Garzicor through a corpse battle followed by his wraith."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"Complete the ghostly presence’s summoning sequence to bring out Garzicor’s Corpse.", "Defeat the corpse within its twenty-minute availability window. Its death summons Garzicor’s Wraith.", "The wraith remains for thirty minutes. Defeat it, then speak with the resulting shade to continue the quest."}}}},
  ["necropolis-vesthon-marijakin-first-confrontation"] = {overview = {"Interrupt Vesthon’s first attempt to seize Hsagra’s spirit."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"Vesthon begins a short ritual scene and calls mercenary guards into the area. Prepare for the guards as the dialogue progresses.", "Drive Vesthon to 20% health to break the confrontation. He is replaced by a retreating form and Hsagra’s shade is released.", "The hostile form has a three-minute despawn timer, so establish combat promptly after the ritual begins."}}}},
  ["necropolis-vesthon-marijakin-and-the-dracoliche-of-hsagra"] = {overview = {"Defeat Vesthon’s seven masters, then confront Vesthon and the Dracoliche of Hsagra."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"Each master has two minions. The minions respawn while their master lives and disappear when that master is defeated, so focus the masters while controlling their servants.", "Masters become actively hostile at 80% health. Coordinate the first damage push so the raid is ready when each one engages.", "Do not drag minions beyond their short leash: returning them increases their damage.", "Defeating all seven masters activates Vesthon. His death replaces Hsagra’s relics with the Dracoliche for the final battle.", "The event has a two-hour cleanup timer. Complete the full sequence before its expiry."}}}},
  ["necropolis-zlandicar-seasonal"] = {overview = {"Respond to Zlandicar’s surgical warnings, destroy his constructs and prevent risen corpses from healing him."}, roles = {{id = "tank", label = "Tanks", tips = {"Hold Zlandicar while the group responds to the marked-target mechanics. Collect each construct or corpse wave promptly."}}, {id = "group", label = "Everyone", tips = {"Read the named warning before moving: Incision requires a stack, Septic requires separation, and Lobotomy requires stopping casts."}}}, phases = {{label = "Operating table", trigger = "70% health", description = "Switch all damage to the surgical constructs while Zlandicar is protected."}, {label = "Risen corpses", trigger = "40% health", description = "Destroy the healing corpses while continuing to respond to the surgical warnings."}, {label = "Final procedure", trigger = "20% health", description = "Warnings arrive more quickly. Clear the final corpse before committing to the boss."}}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"Shared Incision: stack within twenty-five feet of the marked player before the eight-second warning ends. The damage is shared by the players in the stack.", "Septic Burst: move more than twenty-eight feet from the marked player before the eight-second warning ends.", "Lobotomy: the marked player must stop casting before the eight-second warning ends. Casting at resolution causes an interrupt, silence and damage.", "At 70% health, Zlandicar becomes untouchable and summons surgical constructs. Destroy all constructs to expose him; allowing the seventy-two-second operation to time out heals him.", "At 40%, risen corpses begin restoring his health every eight seconds. Kill them promptly.", "At 20%, the warning rotation accelerates. A final priority corpse appears if none remain, so keep add damage available during the burn."}}}},
  ["dragonscalea-living-legacy-marathon"] = {overview = {"Survive increasingly difficult rounds against I.R.A. and its clockwork reinforcements."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"Face I.R.A. away from the raid; stand behind it to avoid Flamethrower.", "Collect bashers, whirlygigs and repair clockworks as they enter.", "Read the immunity label beneath each clockwork's name before choosing control; one enemy can have several immunities.", "Use the respite between completed rounds to recover and prepare for stronger opponents."}}}},
  ["dragonscalea-living-legacy-sprint"] = {overview = {"Push through I.R.A.'s escalating rounds in a focused damage race."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"Keep I.R.A. facing away from the raid and attack from behind to avoid Flamethrower.", "Commit damage efficiently while keeping the tank stable through each stronger round.", "Use each respite to recover quickly and prepare for the next round."}}}},
  ["draniksscar-girplan-spiritleech"] = {overview = {"A beastlord quest calls the Girplan Spiritleech and a ring of spiritminions."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"Have the group prepared before the quest hand-in to Yerika Sisslak.", "The spawn sequence creates eleven spiritminions around the boss.", "Collect the surrounding adds before they overwhelm the group and finish the spirit leech."}}}},
  ["dreadlands-gorenaire-seasonal"] = {overview = {"Seasonal Gorenaire pulses frost damage until her icy shell breaks."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"Players within 60 units take the scripted frost pulse every ten seconds.", "Keep ranged players outside that area when their abilities allow it and cover the melee group with healing.", "At 15%, the pulse stops and the boss becomes more vulnerable to two-handed blunt and two-handed slashing attacks."}}}},
  ["dreadspire-redfang"] = {overview = {"Defeat the screechers, control the bats and pursue Redfang through his disappearances."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"Kill the seven opening screechers to bring out Redfang.", "Control the recurring blooddrinkers while damaging the boss.", "At 65% and 15%, Redfang disappears and the encounter shifts back to bat control.", "Root the voracious bats when appropriate; the script recognizes root as a special response.", "Keep the encounter moving to avoid the idle reset."}}}},
  ["dreadspire-zi-thuuli-of-the-granite-claw"] = {overview = {"Drive Zi-Thuuli away through three encounters before the final confrontation."}, roles = {}, phases = {}, abilities = {}, sections = {{title = "Encounter strategy", paragraphs = {}, bullets = {"Engage promptly when Zi-Thuuli appears; an idle appearance ends after fifteen seconds.", "His first three encounters end at 55%, 50% and 45% health respectively.", "Prepare for the recurring stone spell during longer engagements.", "The next appearance after the third retreat is the killable finale."}}}},
  ["potactics-rallos-zek-the-warlord"] = {overview = {"Defeat the Zek brothers, drive Rallos into the arena, then finish the Warlord amid waves of animated corpses."}, roles = {}, phases = {{label = "The brothers", trigger = "Berik and Grunhork defeated", description = "Defeat Vallon and Tallon; control Vallon’s copies at half health."}, {label = "Upper Rallos", trigger = "Both brothers defeated", description = "Handle elite pairs at 75% and 65%, then push Rallos to 55%."}, {label = "The Warlord", trigger = "Upper Rallos reaches 55%", description = "Move into the arena, control recurring corpse waves and defeat the real Rallos."}}, abilities = {}, sections = {{title = "Encounter guide", paragraphs = {}, bullets = {"Defeat Berik and Grunhork to summon the event versions of Vallon and Tallon. This opening phase has twenty minutes.", "Vallon creates two copies at 50% health. Defeat both real brothers to activate Rallos on the upper level.", "Upper Rallos summons two Decorin Elites at 75% and again at 65%. At 55%, he moves the fight into the arena. This stage has fifteen minutes.", "In the arena, seven corpse adds begin arriving roughly sixty-five seconds into combat and then every fifty-five seconds. Keep an add team ready while damaging the Warlord.", "The final stage has twenty minutes. The script also banishes players beyond seventy-two clients on Rallos’s hate list."}}}},
}
